let payload = msg.payload;

if (typeof payload === "string") {
    payload = JSON.parse(payload);
}

if (!payload || !Array.isArray(payload.data)) {
    node.error("No se encuentra el array de cartas", msg);
    return null;
}

const foilMap = flow.get("foilMap") || {};
const cards = [];
const messages = [];
const now = new Date().toISOString();

function resolvePrice(prices, pref) {
    const order = 
        pref === "E"
            ? [
                { val: prices.eur_etched, cur: "EUR", fin: "etched" },
                { val: prices.usd_etched, cur: "USD", fin: "etched" }
            ]
            : pref === "F"
            ? [
                    { val: prices.eur_foil, cur: "EUR", fin: "foil" },
                    { val: prices.usd_foil, cur: "USD", fin: "foil" }
            ]
            : [
                    { val: prices.eur, cur: "EUR", fin: "normal" },
                    { val: prices.usd, cur: "USD", fin: "normal" }
            ];

    for (const candidate of order) {
        const num = Number(candidate.val);
        if (candidate.val !== null && candidate.val !== undefined && candidate.val !== "" && Number.isFinite(num) && num > 0) {
            return { price: num, currency: candidate.cur, finish: candidate.fin };
        }
    }
    return null;
}

for (const card of payload.data) {
    const clave = `${(card.set || "").toLowerCase()}:${(card.collector_number || "").toLowerCase()}`;
    const finishes = foilMap[clave] || ["NORMAL"];

    for (const pref of finishes) {
        const resolved = resolvePrice(card.prices || {}, pref);

        const finishType = resolved ? resolved.finish : pref === "E" ? "etched" : pref === "F" ? "foil" : "normal";

        const suffix = finishType === "foil" ? " [Foil]" : finishType === "etched" ? " [Etched]": "";
        const uniqueCardId = `${card.id}:${finishType}`;
        const hasPrice = resolved !== null;

        const item = {
            card_id: uniqueCardId,
            name: `${card.name}${suffix}`,
            image_url: card.image_uris?.normal || card.card_faces?.[0]?.image_uris?.normal || "",
            set: card.set,
            rarity: card.rarity,
            finish: finishType,
            available: hasPrice,
            price: hasPrice ? resolved.price : null,
            currency: hasPrice ? resolved.currency : "EUR"
        };

        cards.push(item);

        messages.push({
            payload: {
                ...item,
                timestamp: now,
                source: "scryfall",
                mode: "initial"
            }
        });
    }  
}

// Save cards to context
const prevCards = global.get("cards") || [];
const allActiveCards = prevCards.concat(cards);
global.set("cards", allActiveCards);

const activeIdsList = allActiveCards.map(c => c.card_id);
for (const m of messages) {
    m.payload.active_ids = activeIdsList;
}

node.warn("Processed cards on lot: " + (cards.length + 1));

return messages.length === 0 ? null : [messages];

const card = msg.payload;

// Guardamos el último precio conocido de cada carta
let lastPrices = context.get("lastPrices") || {};

// Identificamos la carta
const id = card.card_id;
const newPrice = Number(card.price);

// Validaciones
if (!id || !Number.isFinite(newPrice) || newPrice <= 0) {
    return null;
}

// Primera vez que vemos la carta: guardamos el precio
if (lastPrices[id] === undefined) {
    lastPrices[id] = newPrice;
    context.set("lastPrices", lastPrices);

    msg.key = id;
    msg.payload = {
        card_id: id,
        name: card.name,
        set: card.set,
        new_price: newPrice,
        currency: card.currency || "EUR",
        image_url: card.image_url || "",
        timestamp: card.timestamp || new Date ().toISOString(),
        alert: "INITIAL_PRICE"
    };
    return msg;
}

// Comparamos con el precio anterior
const oldPrice = lastPrices[id];

const changePercent =
    ((newPrice - oldPrice) / oldPrice) * 100;

// Actualizamos el precio guardado
lastPrices[id] = newPrice;
context.set("lastPrices", lastPrices);

// Si supera el 20 %, generamos alerta
if (Math.abs(changePercent) > 20) {
    msg.key = id;
    msg.payload = {
        card_id: id,
        name: card.name,
        set: card.set,
        old_price: oldPrice,
        new_price: newPrice,
        currency: card.currency || "EUR",
        change_percent: Number(changePercent.toFixed(2)),
        image_url: card.image_url || "",
        timestamp: card.timestamp || new Date ().toISOString(),
        alert: "PRICE_ANOMALY"
    };
    return msg;
}

return null;

let cards = global.get("cards");

if (!cards || cards.length === 0) {
    node.warn("No hay cartas cargadas. Ejecuta primero Scryfall.");
    return null;
}

const messages = [];

for (const card of cards) {
    // Jump cards with no available price on Scryfall
    if (card.available === false || card.price === null || card.price <= 0) {
        continue;
    }

    const oldPrice = card.price;

    // Variación normal entre -5 % y +5 %
    let variation = (Math.random() * 10 - 5) / 100;

    // Un 5 % de probabilidad de una variación brusca
    if (Math.random() < 0.05) {
        variation = Math.random() < 0.5 ? 0.30 : -0.30;
    }

    let newPrice = Math.max(
        0.01,
        Number((oldPrice * (1 + variation)).toFixed(2))
    );

    // Actualizar el precio guardado
    card.price = newPrice;

    messages.push({
        payload: {
            card_id: card.card_id,
            name: card.name,
            image_url: card.image_url,
            set: card.set,
            rarity: card.rarity,
            finish: card.finish,
            available: true,
            price: newPrice,
            currency: card.currency || "EUR",
            timestamp: new Date().toISOString(),
            source: "simulation",
            mode: "simulated"
        }
    });
}

global.set("cards", cards);

node.warn("Mensajes simulados: " + (messages.length + 1));

return messages.length === 0 ? null : [messages];

let store = flow.get("historyStore") || {};
let selectedId = flow.get("selectedCardId") || null;

// CASE A: user has selected another card to visualize
if (typeof msg.payload === "string") {
    selectedId = msg.payload;
    flow.set("selectedCardId", selectedId);

    const cardData = store[selectedId];
    if (!cardData) return [null, null, null, null];

    const chartMsg = {
        topic: `${cardData.name} (${cardData.set.toUpperCase()})`,
        payload: cardData.points
    };
    const imageMsg = {
        topic: cardData.name,
        payload: cardData.image_url || ""
    };
    return [null, chartMsg, null, imageMsg];
}

// CASE B: card price update
const card = msg.payload;
if (!card || !card.card_id || (card.price !== null && typeof card.price !== "number")) {
    return [null, null, null, null];
}

const id = card.card_id;
const timeMs = card.timestamp ? new Date(card.timestamp).getTime() : Date.now();
const isAvailable = card.available !== false && typeof card.price === "number" && card.price > 0;
let listChanged = false;
let selectionChanged = false;

// Sincronize store with active maze: keeps active cards historic data and deletes legacies
if (Array.isArray(card.active_ids) && card.active_ids.length > 0){
    const activeIds = new Set(card.active_ids);
    if (!activeIds.has(id)) {
        return [null, null, null, null];
    }
    for (const storedId of Object.keys(store)) {
        if (!activeIds.has(storedId)) {
            delete store[storedId];
            listChanged = true;
        }
    }
    if (selectedId && !activeIds.has(selectedId)) {
        selectedId = null;
        selectionChanged = true;
    }
}




// if card is new initialize history
if (!store[id]) {
    listChanged = true;
    store[id] = {
        card_id: id,
        name: card.name,
        set: card.set,
        image_url: card.image_url || "",
        currency: card.currency || "EUR",
        available: isAvailable,
        initialPrice: isAvailable ? card.price : null,
        currentPrice: isAvailable ? card.price : null,
        points: []
    };
} else if (!store[id].image_url && card.image_url) {
    store[id].image_url = card.image_url;
}

const isRedundantInitial = card.source === "scryfall" && store[id].points.length > 0;
// Price update only if available
if (isAvailable && !isRedundantInitial) {
    store[id].available = true;
    store[id].currency = card.currency || store[id].currency;
    store[id].currentPrice = card.price;
    store[id].points.push({ x: timeMs, y: card.price });
    if (store[id].points.length > 50) {
        store[id].points.shift();
    }
}

// if there is no card selected, the first one to arrive is selected
if (!selectedId || !store[selectedId]) {
    const keys = Object.keys(store);
    selectedId = keys.length > 0 ? keys[0] : null;
    flow.set("selectedCardId", selectedId);
    selectionChanged = true;
}

flow.set("historyStore", store);

// OUTPUT 1: option update
let dropdownMsg = null;
if (listChanged || selectionChanged) {
    const options = Object.values(store)
        .map( c=> ({ label: `${c.name} (${c.set.toUpperCase()})`, value: c.card_id}))
        .sort((a, b) => a.label.localeCompare(b.label));
    dropdownMsg = { options: options, payload: selectedId };
}

// OUTPUT 2 & 4: graph & image update
let chartMsg = null;
let imageMsg = null;
if (selectedId && store[selectedId] && (id === selectedId || selectionChanged)) {
    const target = store [selectedId];
    chartMsg = {
        topic: `${target.name} (${target.set.toUpperCase()})`,
        payload: target.points
    };
    imageMsg = {
        topic: target.name,
        payload: target.image_url || ""
    }
}

// OUTPUT 3: Top 10 best rises ()
const ranking = Object.values(store)
    .map(c => {
        if (!c.available || c.initialPrice === null || c.currentPrice === null) {
            return {
                Card: c.name,
                Set: c.set.toUpperCase(),
                Initial: "Not available",
                Current: "Not available",
                _sortDiff: -999999,
                "Difference (%)": "N/A"
            };
        }

        const diffPct = ((c.currentPrice - c.initialPrice) / c.initialPrice) * 100;
        const unit = c.currency === "USD" ? "$" : "€";
        return {
            Card: c.name,
            Set: c.set.toUpperCase(),
            Initial: `${c.initialPrice.toFixed(2)} ${unit}`,
            Current: `${c.currentPrice.toFixed(2)} ${unit}`,
            _sortDiff: Number(diffPct.toFixed(2)),
            "Difference (%)": Number(diffPct.toFixed(2))
        };
    })
    .sort((a, b) => b._sortDiff - a._sortDiff)
    .slice(0, 10)
    .map(({ _sortDiff, ...visibleCols }) => visibleCols);

const tableMsg = { payload: ranking };

return [dropdownMsg, chartMsg, tableMsg, imageMsg];

const alertData =
  typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;

if (!alertData || typeof alertData !== "object") {
  return null;
}

const currency = alertData.currency || "EUR";
const pct = Number(alertData.change_percent ?? 0);
const signo = pct > 0 ? "+" : "";
const nombreCarta = alertData.name || alertData.card_id || "Carta";
const setCarta = alertData.set ? ` (${alertData.set})` : "";

const textoTelegram =
  `Alerta de precio (${alertData.alert || "PRICE_ANOMALY"})\n` +
  `Carta: ${nombreCarta}${setCarta}\n` +
  `ID: ${alertData.card_id || "-"}\n` +
  `Precio anterior: ${alertData.old_price} ${currency}\n` +
  `Precio nuevo: ${alertData.new_price} ${currency}\n` +
  `Cambio: ${signo}${pct}%`;

const TOKEN = env.get("TELEGRAM_TOKEN");
const CHAT_ID = env.get("TELEGRAM_CHAT_ID");

msg.url = `https://api.telegram.org/bot${TOKEN}/sendMessage`;
msg.headers = {
  "Content-Type": "application/json"
};
msg.payload = {
  chat_id: CHAT_ID,
  text: textoTelegram
};

return msg;

const texto = typeof msg.payload === "string" ? msg.payload : "";

if (!texto.trim()) {
    node.status({ fill: "red", shape: "ring", text: "Texto vacío" });
    node.error("msg.payload está vacío o no es un string. Revisa la ruta en file in.", msg);
    return null;
}

// Reinitialize cards active list for simulator and dashboard filter
global.set("cards", []);

const lineas = texto.split(/\r?\n/);
const identificadores = [];
const vistos = new Set();
const sinMatch = [];
const foilMap = {};

for (const rawLinea of lineas) {
    const linea = rawLinea.trim();
    if (!linea) continue;

    // Capture: quantity, name, set, collector number and optionally F or E.
    const match = linea.match(/^\d+\s+(.+?)\s+\(([A-Za-z0-9]+)\)\s+([A-Za-z0-9-]+)(?:\s+\*([A-Za-z0-9]+)\*)?$/);

    if (!match) {
        sinMatch.push(linea);
        continue;
    }

    const set = match[2].toLowerCase();
    const collector_number = match[3];
    const finishTag = (match[4] || "NORMAL").toUpperCase();
    const keyCard = `${set}:${collector_number.toLowerCase()}`;
    const clave = `${keyCard}:${finishTag}`;

    // Save finish tag for card
    if (!foilMap[keyCard]) foilMap[keyCard] = [];
    if (!foilMap[keyCard].includes(finishTag)) {
        foilMap[keyCard].push(finishTag);
    }

    if (!vistos.has(clave)) {
        vistos.add(clave);
        identificadores.push({ set, collector_number });
    }
}

flow.set("foilMap", foilMap);

if (sinMatch.length > 0) {
    node.warn(`Líneas no reconocidas (${sinMatch.length}): ${sinMatch.join(" | ")}`);
}

const TAMANO_LOTE = 75;
const lotes = [];

for (let i = 0; i < identificadores.length; i += TAMANO_LOTE) {
    lotes.push({
        headers: {
            "User-Agent": "MTGRadarNodeRED/1.0",
            "Accept": "application/json",
            "Content-Type": "application/json"
        },
        payload: {
            identifiers: identificadores.slice(i, i + TAMANO_LOTE)
        }
    });
}

node.status({
    fill: "green",
    shape: "dot",
    text: `${identificadores.length} cards · ${lotes.length} lot(s)`
});

return lotes.length === 1 ? lotes[0] : [lotes];
